// RegisterUser creates a new user profile and inserts it into the database.
func RegisterUser(o orm.Ormer, username, displayName, email, department, role string) (*UserProfile, error) {
	user := &UserProfile{
		Username:    username,
		DisplayName: displayName,
		Email:       email,
		Department:  department,
		Role:        role,
	}
	_, err := o.Insert(user)
	if err != nil {
		return nil, err
	}
	return user, nil
}

// GenerateUserActivityReport creates an activity report for specified users.
func GenerateUserActivityReport(o orm.Ormer, usernames []string, actionTypeFilter string, startDate, endDate time.Time) ([]UserActivitySummary, error) {
	if len(usernames) == 0 {
		return []UserActivitySummary{}, nil
	}

	// Build the query
	query := `SELECT u.display_name, a.action_type, COUNT(*) as total, SUM(CASE WHEN a.success THEN 1 ELSE 0 END) as success_count, AVG(a.duration_ms) as avg_duration
	FROM user_activity a JOIN user_profile u ON a.user_id = u.id
	WHERE u.username IN (` + placeholders(len(usernames)) + `) AND a.created_at BETWEEN ? AND ?`

	args := make([]interface{}, 0, len(usernames)+2)
	for _, name := range usernames {
		args = append(args, name)
	}
	args = append(args, startDate, endDate)

	if actionTypeFilter != "" {
		query += ` AND a.action_type = ?`
		args = append(args, actionTypeFilter)
	}

	query += ` GROUP BY u.display_name, a.action_type`

	var results []UserActivitySummary
	_, err := o.Raw(query, args...).QueryRows(&results)
	if err != nil {
		return nil, err
	}
	return results, nil
}

// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	validFields := map[string]bool{
		"department":   true,
		"role":         true,
		"display_name": true,
	}
	if !validFields[groupByField] {
		return []map[string]interface{}{}, nil
	}

	query := `SELECT u.` + groupByField + ` as group_value, COUNT(DISTINCT u.id) as user_count, COUNT(a.id) as total_activities
	FROM user_profile u LEFT JOIN user_activity a ON u.id = a.user_id
	WHERE u.department IN (` + placeholders(len(departments)) + `)
	GROUP BY u.` + groupByField

	args := make([]interface{}, len(departments))
	for i, dept := range departments {
		args[i] = dept
	}

	var rawResults []struct {
		GroupValue      string `orm:"column(group_value)"`
		UserCount       int    `orm:"column(user_count)"`
		TotalActivities int    `orm:"column(total_activities)"`
	}
	_, err := o.Raw(query, args...).QueryRows(&rawResults)
	if err != nil {
		return nil, err
	}

	results := make([]map[string]interface{}, len(rawResults))
	for i, r := range rawResults {
		results[i] = map[string]interface{}{
			"group_value":      r.GroupValue,
			"user_count":       r.UserCount,
			"total_activities": r.TotalActivities,
		}
	}
	return results, nil
}

// placeholders generates a string of placeholders like "?, ?, ?" for the given count
func placeholders(n int) string {
	if n <= 0 {
		return ""
	}
	result := make([]byte, 0, n*2-1)
	for i := 0; i < n; i++ {
		if i > 0 {
			result = append(result, ',', ' ')
		}
		result = append(result, '?')
	}
	return string(result)
}

