		args = append(args, actionTypeFilter)
	}

	query += " GROUP BY u.display_name, a.action_type"

	var results []UserActivitySummary
	_, err := o.Raw(query, args...).QueryRows(&results)
	if err != nil {
		return nil, fmt.Errorf("failed to query activity report: %w", err)
	}

	return results, nil
}

// GenerateDepartmentReport creates a summary report grouped by a specified field.
func GenerateDepartmentReport(o orm.Ormer, departments []string, groupByField string) ([]map[string]interface{}, error) {
	if o == nil {
		return nil, errors.New("orm instance is nil")
	}

	// Validate groupByField
	validFields := map[string]bool{
		"department":   true,
		"role":         true,
		"display_name": true,
	}
	if !validFields[groupByField] {
		return nil, fmt.Errorf("invalid groupByField: %s, must be one of: department, role, display_name", groupByField)
	}

	if len(departments) == 0 {
		return []map[string]interface{}{}, nil
	}

	// Build the query with dynamic placeholders for departments
	placeholders := make([]string, len(departments))
	args := make([]interface{}, 0, len(departments))
	for i, dept := range departments {
		placeholders[i] = "?"
		args = append(args, dept)
	}

	query := fmt.Sprintf(`
		SELECT u.%s as group_value, 
		       COUNT(DISTINCT u.id) as user_count, 
		       COUNT(a.id) as total_activities
		FROM user_profile u
		LEFT JOIN user_activity a ON u.id = a.user_id
		WHERE u.department IN (%s)
		GROUP BY u.%s
	`, groupByField, strings.Join(placeholders, ","), groupByField)

	var rawResults []struct {
		GroupValue      string `orm:"column(group_value)"`
		UserCount       int    `orm:"column(user_count)"`
		TotalActivities int    `orm:"column(total_activities)"`
	}

	_, err := o.Raw(query, args...).QueryRows(&rawResults)
	if err != nil {
		return nil, fmt.Errorf("failed to query department report: %w", err)
	}

	// Convert to the required map format
	results := make([]map[string]interface{}, len(rawResults))
	for i, r := range rawResults {
		results[i] = map[string]interface{}{
			"group_value":      r.GroupValue,
			"user_count":       r.UserCount,
			"total_activities": r.TotalActivities,
		}
	}

	return results, nil
}

